  "opportunityEvidence": [
    {
      "statement": "The Schedule Service form asks users to select from 'Air Conditioning Heating Plumbing Sewers Drains' even though the company is a plumbing, boiler, drain, and water treatment contractor.",
      "label": "fact",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/schedule-service/",
      "quote": "Service Needed * Air Conditioning Heating Plumbing Sewers Drains"
    },
    {
      "statement": "Both the Contact Us and Schedule Service pages submit via standard web POST requests to the website rather than providing real-time appointment booking or instant interactive triage.",
      "label": "inference",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/schedule-service/",
      "quote": null
    },
    {
      "statement": "The Coupons page displays a $50 off plumbing service offer with an expiration date of 7/31/25.",
      "label": "fact",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/about/coupons/",
      "quote": "Not to be combined with any other offer. Expires 7/31/25."
    },
    {
      "statement": "The Coupons page displays a $99 Water Heater Flush offer with an expiration date of 5/31/25.",
      "label": "fact",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/about/coupons/",
      "quote": "$99 Water Heater Flush Not to be combined with any other offer. Expires 5/31/25."
    },
    {
      "statement": "The website lists two different phone numbers across pages: [redacted] in the header and [redacted] in the body text of the About and Coupons pages.",
      "label": "fact",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/about/",
      "quote": "Call us at [redacted] or fill out our online contact form to get started."
    },
    {
      "statement": "A single email address, [redacted], is published across the site for dispatch, general contact, privacy requests, and terms inquiries.",
      "label": "fact",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/terms-and-conditions/",
      "quote": "By email: [redacted]· By phone number: [redacted]"
    }
  ],
  "problems": [
    {
      "problem": "The online 'Schedule Service' form is an uncustomized static web form (including irrelevant 'Air Conditioning' and 'Heating' options) rather than an interactive booking or instant lead-capture workflow.",
      "label": "fact",
      "basis": "Observed directly on https://plumbingsolutionsofidaho.com/schedule-service/, where the form posts to the WordPress URL and lists 'Service Needed * Air Conditioning Heating Plumbing Sewers Drains'."
    },
    {
      "problem": "Website marketing and conversion assets show signs of agency template neglect, including coupons expired in May and July 2025, New York governing-law boilerplate, and secondary phone numbers embedded in body copy.",
      "label": "inference",
      "basis": "Inferred from https://plumbingsolutionsofidaho.com/about/coupons/ (2025 expiration dates), https://plumbingsolutionsofidaho.com/terms-and-conditions/ (New York law), and https://plumbingsolutionsofidaho.com/about/ (secondary phone number [redacted])."
    },
    {
      "problem": "Web form submissions from paid ads and organic visitors may experience delays before being entered into field-service software and receiving a callback, especially after hours or during peak dispatch periods.",
      "label": "hypothesis",
      "basis": "While static.servicetitan.com is referenced on the site, the Schedule Service and Contact Us pages use standard WordPress forms rather than an embedded real-time scheduler or instant chat widget."
    },
    {
      "problem": "Incoming emails to the single published address ([redacted]) may mix urgent customer dispatch requests with vendor, billing, and general inquiries.",
      "label": "hypothesis",
      "basis": "[redacted] is the sole email address published across all pages of the website."
    },
    {
      "problem": "Leadership may lack a consolidated weekly view combining paid ad spend across Google, Bing, and Facebook with booked job revenue and close rates.",
      "label": "hypothesis",
      "basis": "The Privacy Policy and page scripts show multiple advertising and tracking platforms in use, which commonly require manual reconciliation with field-service and accounting data."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Native field-service management web booking widget and lead integration (associated with static.servicetitan.com)",
      "addresses": "Direct online scheduling and automated ingestion of web form leads into dispatch software",
      "alreadyOwned": true
    },
    {
      "solution": "Website agency content and form updates via MountainMarketingGroup.net",
      "addresses": "Correcting the 'Air Conditioning / Heating' dropdown options on the Schedule Service form and updating expired 2025 coupon dates",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "One-week audit ($500 fixed price, credited toward any fix ordered within 30 days) measuring how many calls, web form submissions, and quotes slip through across phone and web channels.",
      "problem": "Potential delay or leakage between paid ad clicks, static WordPress form submissions, and booked jobs in dispatch.",
      "whyNotExistingSoftware": "Even when a contractor owns field-service software, an independent audit across website forms, call tracking numbers, and inbox logs identifies where leads are dropping before configuring or building automation."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Automated pipeline ($1,800 setup plus $149/month) ensuring every web form and lead source lands in the field-service software within two minutes, triggers an instant SMS/email reply, and alerts dispatch until followed up.",
      "problem": "Static WordPress forms on Contact Us and Schedule Service may rely on manual email reading at [redacted] before a lead is entered and contacted.",
      "whyNotExistingSoftware": "If their current WordPress form setup is not natively pushing structured lead records into their dispatch queue with instant two-minute SMS replies, a lightweight webhook-to-API bridge solves it without redesigning the website."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "Automated weekly one-page report ($1,200 setup plus $99/month) showing booked revenue, close rate, average ticket, cost per booked job by lead source, and accounts receivable.",
      "problem": "Reconciling return on ad spend across Google Ads, Bing Ads, Facebook, and third-party ad trackers against actual booked plumbing revenue.",
      "whyNotExistingSoftware": "Native field-service dashboards often require complex ad-account mapping or high-tier marketing add-ons to combine multi-channel ad spend and accounting receivables into a single Monday digest."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "The website runs on a standard stack with WordPress forms (frm.min.js) and already includes SMS opt-in checkboxes for appointment reminders and text communications on both the Contact Us and Schedule Service forms. Connecting form webhooks, email parsing, and ad-spend APIs to dispatch software is technically straightforward."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "Deterministic workflow automation (webhooks, API integrations, and scheduled data aggregation) should handle lead routing, instant SMS confirmation, and weekly KPI reporting. AI agents are well-suited for classifying free-text form messages, triaging the shared [redacted] inbox, and drafting initial responses, while human dispatchers must control emergency prioritization and technician assignment."
  },
  "humanReview": [
    "Human dispatcher verification for any lead indicating an active plumbing emergency (such as burst pipes, active flooding, or sewage backups).",
    "Human approval before finalizing technician dispatch assignments or modifying schedule slots.",
    "Human review of drafted replies in the [redacted] inbox before sending non-standard quotes or commercial commitments."
  ],
  "risks": [
    {
      "type": "compliance",
      "description": "Automated SMS replies must strictly respect the user's SMS opt-in checkbox state on the Contact Us and Schedule Service forms and honor STOP/HELP commands under TCPA and carrier 10DLC rules."
    },
    {
      "type": "operational",
      "description": "Plumbing Solutions of Idaho advertises 24/7 emergency response; an automated reply must never give a customer with an active water leak the false impression that a truck is already rolling before a live dispatcher or on-call tech confirms."
    },
    {
      "type": "security",
      "description": "Customer names, phone numbers, emails, and service addresses must be transmitted over encrypted connections with least-privilege API credentials."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "Illustrative: $495 per month ($5,940 per year) at the baseline promotional service level, calculated from the site's published $99 Water Heater Flush price times an assumed 5 additional captured leads per month (standard repair and installation prices are not listed on the website).",
    "implementationCost": "$500 fixed price for the Revenue Leak Check (credited in full toward any fix ordered within 30 days); $1,800 setup plus $149/month for the Lead-to-job pipeline; or $1,200 setup plus $99/month for Owner's Monday numbers.",
    "assumptions": [
      "The only specific service price published on the website is the $99 Water Heater Flush (alongside a $50 Off Any Plumbing Service coupon) on https://plumbingsolutionsofidaho.com/about/coupons/.",
      "Assumes 5 otherwise-missed or delayed web/phone leads per month are converted into booked jobs at the $99 published price ($99 x 5 = $495/month illustrative baseline).",
      "Standard diagnostic, repair, sewer, and installation ticket prices are not published on the website and are therefore excluded from this calculation."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / President",
      "General Manager",
      "Operations / Dispatch Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "When a homeowner submits the 'Schedule Service' form on your website—especially after hours—how does that request currently get into your dispatch board, and how quickly do they get a text or call back?",
      "Did you know your online Schedule Service form currently lists 'Air Conditioning' and 'Heating' in the dropdown, and your Coupons page still shows 2025 expiration dates?",
      "Since you reference ServiceTitan on your site, are your WordPress forms automatically creating bookings/leads inside it, or is dispatch manually entering emails from [redacted]?",
      "With two phone numbers showing on the site ([redacted] in the header and [redacted] in page copy) plus Google, Bing, and Facebook ads running, how do you currently track which ad channel produces booked plumbing revenue each week?"
    ],
    "outreachSubject": "Quick note on your Schedule Service form / Plumbing Solutions of Idaho",
    "outreachBody": "Hi Plumbing Solutions of Idaho team,\n\nI was looking through plumbingsolutionsofidaho.com and noticed a couple of small items on your site that might be costing you leads:\n\n1. On your Schedule Service page, the 'Service Needed' dropdown asks customers to choose between 'Air Conditioning' and 'Heating' alongside Plumbing, Sewers, and Drains.\n2. Your Coupons page still shows 2025 expiration dates (5/31/25 and 7/31/25).\n\nEven if you have your web agency clean those up, I wanted to ask how those WordPress form submissions currently reach your dispatch board. I run ForgeX—we help home-service contractors connect their web forms and call/lead channels directly into their field-service software with an instant reply in under two minutes.\n\nWe offer a fixed-price $500 Revenue Leak Check where, in one week, we audit how many calls, web leads, and quotes slip through the cracks (and the $500 is credited in full if you order a fix within 30 days). We don't promise specific results, and if your current software already handles this end-to-end, we'll tell you straight up.\n\nWould the owner or operations manager be open to a 10-minute chat next week?\n\nBest regards,\n\n[FOUNDER NAME]\n[FOUNDER TITLE], ForgeX\n[FORGEX POSTAL ADDRESS]\n[FORGEX PHONE / WEBSITE]\n\nIf you prefer not to receive future emails from us, simply reply with \"unsubscribe\" or [OPT-OUT MECHANISM] and we will remove you immediately."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://plumbingsolutionsofidaho.com/",
        "usedFor": "Business identity, address, 24/7 service claims, review count, contact email, and referenced hosts (static.servicetitan.com, clickcease.com, app.realworklabs.com)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/",
        "usedFor": "2005 founding year, Meridian location, residential/commercial mission, and secondary phone number [redacted]"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/meet-the-team/",
        "usedFor": "Checked for named owners, executives, or managers (none listed)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/contact-us/",
        "usedFor": "Contractor license PLB-C-12709, contact form structure, and SMS opt-in checkboxes"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/schedule-service/",
        "usedFor": "Schedule Service form structure, frm.min.js script, and uncustomized 'Air Conditioning Heating' dropdown options"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/coupons/",
        "usedFor": "Published promotional pricing ($99 Water Heater Flush, $50 Off) and expired 2025 dates"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/careers/",
        "usedFor": "Employee benefits evidence and reference to plumbingsolutionsofidaho.applicantpro.com"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/financing/",
        "usedFor": "GreenSky and Service Finance Company, LLC usage"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/terms-and-conditions/",
        "usedFor": "SMS messaging terms, New York governing law boilerplate, and [redacted] usage"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/privacy-policy/",
        "usedFor": "Explicit disclosures of Google Analytics, Google Ads (AdWords), Bing Ads Remarketing, and Facebook remarketing"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/community/",
        "usedFor": "2024 BBB Torch Award for Ethics and Meridian Chamber of Commerce Business of the Year recognition"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/meridian-plumbers/",
        "usedFor": "Family-owned business statement, licensing/bonding claims, and 24-48 hour non-emergency scheduling policy"
      }
    ],
    "limitations": [
      "The website does not name any individual owners, executives, or managers on the About or Meet The Team pages.",
      "Exact employee headcount is not stated on the website.",
      "Although static.servicetitan.com is referenced on the site, the internal configuration of their field-service software and whether WordPress form submissions sync automatically into it cannot be verified from public pages alone.",
      "Standard service and installation prices are not published on the website; only coupon offers ($99 Water Heater Flush and $50 Off) are shown."
    ]
  },
  "qualification": {
    "category": "pursue now",
    "rationale": "Plumbing Solutions of Idaho is a family-owned plumbing contractor in Meridian, ID (founded in 2005, 1,000+ Google reviews, active paid advertising across Google, Bing, and Facebook) that fits ForgeX's target segment. Observable facts on the website—including a static WordPress 'Schedule Service' form with uncustomized 'Air Conditioning / Heating' options, expired 2025 coupons, multiple phone numbers in page text, and a single shared [redacted] email address—point to concrete lead-capture and intake hygiene gaps that ForgeX's Revenue Leak Check and Lead-to-job pipeline directly address, and a permitted business contact channel is available."
  }
}
